(() => {
  const WIDGET_ID = "xingji-workbuddy-widget-frame";
  const APP_HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>星寄｜追星悬浮球工作台</title>\n  <style>\n    :root {\n      --primary: #8d5cf6;\n      --primary-dark: #653fd1;\n      --primary-soft: #f2ebff;\n      --accent: #c7a3ff;\n      --bg: #fbf8ff;\n      --card: rgba(255, 255, 255, 0.78);\n      --text: #2f2640;\n      --muted: #7a6f8e;\n      --line: rgba(141, 92, 246, 0.18);\n      --shadow: 0 18px 50px rgba(95, 62, 160, 0.22);\n      --radius-xl: 28px;\n      --radius-lg: 20px;\n      --radius-md: 14px;\n      --font: \"Inter\", \"PingFang SC\", \"Microsoft YaHei\", system-ui, sans-serif;\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    body {\n      margin: 0;\n      min-height: 100vh;\n      font-family: var(--font);\n      color: var(--text);\n      background:\n        radial-gradient(circle at 15% 20%, rgba(199, 163, 255, 0.45), transparent 30%),\n        radial-gradient(circle at 88% 12%, rgba(255, 211, 235, 0.7), transparent 28%),\n        linear-gradient(135deg, #fbf8ff 0%, #f4edff 52%, #fff7fd 100%);\n      overflow: hidden;\n    }\n\n    button,\n    input,\n    select,\n    textarea {\n      font: inherit;\n    }\n\n    button {\n      border: 0;\n      cursor: pointer;\n    }\n\n    .ambient {\n      position: fixed;\n      inset: 0;\n      pointer-events: none;\n      overflow: hidden;\n    }\n\n    .star {\n      position: absolute;\n      width: 6px;\n      height: 6px;\n      border-radius: 50%;\n      background: var(--accent);\n      opacity: 0.4;\n      animation: floatStar 8s ease-in-out infinite;\n    }\n\n    .star:nth-child(1) { left: 9%; top: 18%; animation-delay: 0s; }\n    .star:nth-child(2) { left: 42%; top: 8%; animation-delay: 1s; }\n    .star:nth-child(3) { left: 78%; top: 22%; animation-delay: 2s; }\n    .star:nth-child(4) { left: 18%; top: 76%; animation-delay: 1.5s; }\n    .star:nth-child(5) { left: 86%; top: 82%; animation-delay: 0.6s; }\n\n    @keyframes floatStar {\n      0%, 100% { transform: translateY(0) scale(1); opacity: 0.38; }\n      50% { transform: translateY(-18px) scale(1.25); opacity: 0.72; }\n    }\n\n    .welcome {\n      position: fixed;\n      inset: 0;\n      display: grid;\n      place-items: center;\n      padding: 28px;\n      text-align: center;\n    }\n\n    .welcome-card {\n      width: min(760px, calc(100vw - 56px));\n      padding: 42px;\n      border: 1px solid var(--line);\n      border-radius: 36px;\n      background: rgba(255, 255, 255, 0.56);\n      box-shadow: var(--shadow);\n      backdrop-filter: blur(22px);\n    }\n\n    .welcome-card h1 {\n      margin: 0 0 12px;\n      font-size: clamp(42px, 8vw, 76px);\n      letter-spacing: 0.16em;\n      color: var(--primary-dark);\n    }\n\n    .welcome-card p {\n      margin: 0 auto 24px;\n      max-width: 560px;\n      line-height: 1.8;\n      color: var(--muted);\n    }\n\n    .open-main {\n      display: inline-flex;\n      align-items: center;\n      gap: 10px;\n      padding: 14px 22px;\n      border-radius: 999px;\n      color: white;\n      background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n      box-shadow: 0 12px 24px rgba(101, 63, 209, 0.26);\n    }\n\n    .float-ball {\n      position: fixed;\n      right: 28px;\n      bottom: 28px;\n      width: 72px;\n      height: 72px;\n      z-index: 30;\n      display: grid;\n      place-items: center;\n      color: white;\n      border-radius: 50%;\n      background: radial-gradient(circle at 30% 22%, #fff 0 5%, var(--accent) 6% 22%, var(--primary) 55%, var(--primary-dark) 100%);\n      box-shadow: 0 18px 42px rgba(101, 63, 209, 0.36);\n      user-select: none;\n      transition: transform 0.2s ease, box-shadow 0.2s ease;\n      animation: ballPopIn 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) both;\n    }\n\n    @keyframes ballPopIn {\n      0% { transform: scale(0); opacity: 0; }\n      60% { transform: scale(1.15); opacity: 1; }\n      100% { transform: scale(1); opacity: 1; }\n    }\n\n    .float-ball:hover {\n      transform: translateY(-3px) scale(1.03);\n      box-shadow: 0 22px 54px rgba(101, 63, 209, 0.44);\n    }\n\n    .float-ball .logo {\n      display: grid;\n      place-items: center;\n      width: 48px;\n      height: 48px;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, 0.18);\n      font-size: 22px;\n      font-weight: 800;\n      letter-spacing: 0.08em;\n    }\n\n    .badge {\n      position: absolute;\n      right: 1px;\n      top: 4px;\n      min-width: 20px;\n      height: 20px;\n      display: none;\n      place-items: center;\n      padding: 0 6px;\n      border: 2px solid white;\n      border-radius: 999px;\n      color: white;\n      background: #ff4d7d;\n      font-size: 12px;\n      font-weight: 700;\n    }\n\n    .badge.show {\n      display: grid;\n    }\n\n    .quick-panel {\n      position: fixed;\n      right: 28px;\n      bottom: 112px;\n      z-index: 25;\n      width: 330px;\n      transform-origin: bottom right;\n      display: none;\n      padding: 18px;\n      border: 1px solid var(--line);\n      border-radius: 26px;\n      background: var(--card);\n      box-shadow: var(--shadow);\n      backdrop-filter: blur(24px);\n    }\n\n    .quick-panel.show {\n      display: block;\n      animation: pop 0.18s ease-out;\n    }\n\n    @keyframes pop {\n      from { opacity: 0; transform: scale(0.94) translateY(10px); }\n      to { opacity: 1; transform: scale(1) translateY(0); }\n    }\n\n    .quick-head {\n      display: flex;\n      justify-content: space-between;\n      gap: 12px;\n      align-items: flex-start;\n      margin-bottom: 14px;\n    }\n\n    .quick-head h2,\n    .panel-title h2 {\n      margin: 0;\n      font-size: 22px;\n      color: var(--primary-dark);\n    }\n\n    .quick-head p,\n    .panel-title p {\n      margin: 4px 0 0;\n      color: var(--muted);\n      font-size: 13px;\n    }\n\n    .chip {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 7px 10px;\n      border-radius: 999px;\n      color: var(--primary-dark);\n      background: var(--primary-soft);\n      font-size: 12px;\n      font-weight: 700;\n    }\n\n    .quick-stats {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 10px;\n      margin: 12px 0 16px;\n    }\n\n    .stat {\n      padding: 12px 10px;\n      border: 1px solid var(--line);\n      border-radius: 18px;\n      background: rgba(255, 255, 255, 0.58);\n      text-align: center;\n    }\n\n    .stat strong {\n      display: block;\n      font-size: 20px;\n      color: var(--primary-dark);\n    }\n\n    .stat span {\n      display: block;\n      margin-top: 3px;\n      font-size: 12px;\n      color: var(--muted);\n    }\n\n    .quick-actions {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 10px;\n    }\n\n    .btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      min-height: 42px;\n      padding: 10px 14px;\n      border-radius: 15px;\n      color: white;\n      background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n      font-weight: 700;\n      box-shadow: 0 10px 22px rgba(101, 63, 209, 0.2);\n    }\n\n    .btn.ghost {\n      color: var(--primary-dark);\n      background: var(--primary-soft);\n      box-shadow: none;\n    }\n\n    .btn.line {\n      color: var(--primary-dark);\n      background: transparent;\n      border: 1px solid var(--line);\n      box-shadow: none;\n    }\n\n    .app-shell {\n      position: fixed;\n      inset: 28px;\n      z-index: 20;\n      display: none;\n      grid-template-columns: 280px minmax(0, 1fr);\n      border: 1px solid var(--line);\n      border-radius: var(--radius-xl);\n      background: rgba(255, 255, 255, 0.68);\n      box-shadow: var(--shadow);\n      overflow: hidden;\n      backdrop-filter: blur(28px);\n    }\n\n    .app-shell.show {\n      display: grid;\n    }\n\n    .mobile-topbar,\n    .drawer-mask,\n    .drawer-close,\n    .menu-btn {\n      display: none;\n    }\n\n    .sidebar {\n      display: flex;\n      flex-direction: column;\n      gap: 18px;\n      min-height: 0;\n      padding: 24px 18px;\n      border-right: 1px solid var(--line);\n      background:\n        linear-gradient(180deg, rgba(255,255,255,0.5), rgba(255,255,255,0.2)),\n        linear-gradient(150deg, var(--primary-soft), rgba(255,255,255,0.66));\n    }\n\n    .brand {\n      display: flex;\n      gap: 12px;\n      align-items: center;\n      padding: 6px 8px 16px;\n      border-bottom: 1px solid var(--line);\n    }\n\n    .brand-icon {\n      width: 50px;\n      height: 50px;\n      display: grid;\n      place-items: center;\n      border-radius: 18px;\n      color: white;\n      background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n      font-weight: 900;\n      box-shadow: 0 14px 30px rgba(101, 63, 209, 0.23);\n    }\n\n    .brand h1 {\n      margin: 0;\n      color: var(--primary-dark);\n      font-size: 25px;\n      letter-spacing: 0.12em;\n    }\n\n    .brand p {\n      margin: 3px 0 0;\n      font-size: 12px;\n      color: var(--muted);\n    }\n\n    .nav-scroll {\n      overflow: auto;\n      padding-right: 4px;\n    }\n\n    .nav-group {\n      margin-bottom: 18px;\n    }\n\n    .nav-group-title {\n      margin: 0 0 8px 8px;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 800;\n      letter-spacing: 0.04em;\n    }\n\n    .nav-item {\n      width: 100%;\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      min-height: 42px;\n      margin: 5px 0;\n      padding: 10px 12px;\n      border-radius: 15px;\n      color: var(--text);\n      background: transparent;\n      text-align: left;\n      transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;\n    }\n\n    .nav-item:hover {\n      background: rgba(255, 255, 255, 0.54);\n      transform: translateX(2px);\n    }\n\n    .nav-item.active {\n      color: white;\n      background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n      box-shadow: 0 10px 24px rgba(101, 63, 209, 0.18);\n    }\n\n    .sidebar-foot {\n      margin-top: auto;\n      display: grid;\n      gap: 10px;\n    }\n\n    .content {\n      min-width: 0;\n      display: flex;\n      flex-direction: column;\n      min-height: 0;\n    }\n\n    .topbar {\n      display: flex;\n      justify-content: space-between;\n      gap: 16px;\n      align-items: center;\n      padding: 22px 26px;\n      border-bottom: 1px solid var(--line);\n      background: rgba(255, 255, 255, 0.38);\n    }\n\n    .panel-title h2 {\n      font-size: 24px;\n    }\n\n    .top-actions {\n      display: flex;\n      gap: 10px;\n      align-items: center;\n      flex-wrap: wrap;\n      justify-content: flex-end;\n    }\n\n    .main {\n      min-height: 0;\n      flex: 1;\n      overflow: auto;\n      padding: 24px 26px;\n    }\n\n    .grid {\n      display: grid;\n      grid-template-columns: repeat(12, 1fr);\n      gap: 16px;\n    }\n\n    .card {\n      padding: 18px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius-lg);\n      background: var(--card);\n      box-shadow: 0 10px 28px rgba(80, 59, 120, 0.08);\n    }\n\n    .card h3 {\n      margin: 0 0 12px;\n      color: var(--primary-dark);\n      font-size: 17px;\n    }\n\n    .col-4 { grid-column: span 4; }\n    .col-5 { grid-column: span 5; }\n    .col-6 { grid-column: span 6; }\n    .col-7 { grid-column: span 7; }\n    .col-8 { grid-column: span 8; }\n    .col-12 { grid-column: span 12; }\n\n    .form {\n      display: grid;\n      gap: 10px;\n    }\n\n    .field {\n      display: grid;\n      gap: 6px;\n    }\n\n    .field label {\n      font-size: 12px;\n      color: var(--muted);\n      font-weight: 800;\n    }\n\n    input,\n    select,\n    textarea {\n      width: 100%;\n      border: 1px solid var(--line);\n      border-radius: 14px;\n      outline: none;\n      padding: 11px 12px;\n      color: var(--text);\n      background: rgba(255, 255, 255, 0.76);\n    }\n\n    textarea {\n      min-height: 112px;\n      resize: vertical;\n      line-height: 1.7;\n    }\n\n    input:focus,\n    select:focus,\n    textarea:focus {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 4px rgba(141, 92, 246, 0.12);\n    }\n\n    .people-list,\n    .entry-list {\n      display: grid;\n      gap: 12px;\n    }\n\n    .person-card,\n    .entry-card {\n      display: flex;\n      gap: 12px;\n      align-items: center;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 18px;\n      background: rgba(255, 255, 255, 0.64);\n    }\n\n    .person-card.active {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 4px rgba(141, 92, 246, 0.12);\n    }\n\n    .avatar {\n      flex: 0 0 54px;\n      width: 54px;\n      height: 54px;\n      display: grid;\n      place-items: center;\n      border-radius: 20px;\n      color: white;\n      background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n      overflow: hidden;\n      font-weight: 900;\n    }\n\n    .avatar img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n    }\n\n    .person-meta,\n    .entry-meta {\n      min-width: 0;\n      flex: 1;\n    }\n\n    .person-meta strong,\n    .entry-meta strong {\n      display: block;\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n    }\n\n    .person-meta span,\n    .entry-meta span {\n      display: block;\n      margin-top: 4px;\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .color-dot {\n      width: 22px;\n      height: 22px;\n      flex: 0 0 22px;\n      border: 2px solid white;\n      border-radius: 50%;\n      box-shadow: 0 0 0 1px var(--line);\n    }\n\n    .q-card {\n      position: relative;\n      min-height: 360px;\n      overflow: hidden;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      background:\n        radial-gradient(circle at 72% 24%, rgba(255, 255, 255, 0.72), transparent 22%),\n        linear-gradient(145deg, var(--primary-soft), rgba(255,255,255,0.7));\n    }\n\n    .q-figure {\n      align-self: center;\n      width: 180px;\n      height: 210px;\n      display: grid;\n      place-items: center;\n      margin: 8px 0 16px;\n      border: 8px solid rgba(255, 255, 255, 0.7);\n      border-radius: 42% 42% 38% 38%;\n      background: linear-gradient(135deg, rgba(255,255,255,0.7), var(--primary-soft));\n      box-shadow: inset 0 -18px 42px rgba(141, 92, 246, 0.12), 0 20px 38px rgba(80,59,120,0.12);\n      overflow: hidden;\n      cursor: pointer;\n      animation: idle 3s ease-in-out infinite;\n    }\n\n    .q-figure img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n    }\n\n    .q-placeholder {\n      font-size: 76px;\n      filter: drop-shadow(0 12px 18px rgba(101, 63, 209, 0.18));\n    }\n\n    @keyframes idle {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-8px); }\n    }\n\n    .bubble {\n      position: absolute;\n      right: 18px;\n      top: 82px;\n      max-width: 210px;\n      display: none;\n      padding: 12px 14px;\n      border-radius: 18px 18px 6px 18px;\n      color: var(--primary-dark);\n      background: white;\n      box-shadow: 0 12px 26px rgba(80,59,120,0.14);\n      line-height: 1.55;\n      font-size: 13px;\n    }\n\n    .bubble.show {\n      display: block;\n    }\n\n    .empty {\n      padding: 18px;\n      border: 1px dashed var(--line);\n      border-radius: 18px;\n      color: var(--muted);\n      text-align: center;\n      background: rgba(255,255,255,0.42);\n    }\n\n    .toolbar {\n      display: flex;\n      gap: 10px;\n      flex-wrap: wrap;\n      margin-bottom: 14px;\n    }\n\n    .theme-grid {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 10px;\n    }\n\n    .theme-card {\n      min-height: 82px;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 18px;\n      background: rgba(255,255,255,0.62);\n      text-align: left;\n    }\n\n    .swatches {\n      display: flex;\n      gap: 5px;\n      margin-bottom: 10px;\n    }\n\n    .swatches i {\n      width: 20px;\n      height: 20px;\n      border-radius: 50%;\n    }\n\n    .theme-card strong {\n      display: block;\n      font-size: 13px;\n      color: var(--text);\n    }\n\n    .theme-card span {\n      display: block;\n      margin-top: 4px;\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .chat {\n      display: grid;\n      gap: 12px;\n    }\n\n    .chat-log {\n      min-height: 300px;\n      max-height: 420px;\n      overflow: auto;\n      display: grid;\n      gap: 10px;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 18px;\n      background: rgba(255,255,255,0.48);\n    }\n\n    .msg {\n      max-width: 78%;\n      padding: 10px 12px;\n      border-radius: 16px;\n      line-height: 1.65;\n      font-size: 14px;\n    }\n\n    .msg.user {\n      justify-self: end;\n      color: white;\n      background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n      border-bottom-right-radius: 5px;\n    }\n\n    .msg.ai {\n      justify-self: start;\n      color: var(--text);\n      background: white;\n      border-bottom-left-radius: 5px;\n    }\n\n    .modal-mask {\n      position: fixed;\n      inset: 0;\n      z-index: 50;\n      display: none;\n      place-items: center;\n      padding: 24px;\n      background: rgba(43, 31, 68, 0.28);\n      backdrop-filter: blur(8px);\n    }\n\n    .modal-mask.show {\n      display: grid;\n    }\n\n    .modal {\n      width: min(760px, 96vw);\n      max-height: 86vh;\n      overflow: auto;\n      padding: 22px;\n      border: 1px solid var(--line);\n      border-radius: 28px;\n      background: rgba(255,255,255,0.9);\n      box-shadow: var(--shadow);\n    }\n\n    .modal-head {\n      display: flex;\n      justify-content: space-between;\n      gap: 16px;\n      align-items: center;\n      margin-bottom: 16px;\n    }\n\n    .modal-head h2 {\n      margin: 0;\n      color: var(--primary-dark);\n    }\n\n    .save-state {\n      position: fixed;\n      left: 28px;\n      bottom: 28px;\n      z-index: 60;\n      display: none;\n      padding: 10px 14px;\n      border-radius: 999px;\n      color: var(--primary-dark);\n      background: rgba(255,255,255,0.86);\n      border: 1px solid var(--line);\n      box-shadow: 0 10px 28px rgba(80,59,120,0.12);\n      font-size: 13px;\n    }\n\n    .save-state.show {\n      display: block;\n      animation: pop 0.16s ease-out;\n    }\n\n    @media (max-width: 980px) {\n      .app-shell {\n        inset: 14px;\n        grid-template-columns: minmax(0, 1fr);\n        grid-template-rows: auto minmax(0, 1fr);\n      }\n\n      .sidebar {\n        max-height: none;\n        min-width: 0;\n        width: 100%;\n        overflow: hidden;\n        border-right: 0;\n        border-bottom: 1px solid var(--line);\n      }\n\n      .nav-scroll {\n        display: flex;\n        width: 100%;\n        min-width: 0;\n        max-width: 100%;\n        gap: 10px;\n        overflow-x: auto;\n        overflow-y: hidden;\n        padding: 0 2px 6px;\n        scroll-snap-type: x proximity;\n        -webkit-overflow-scrolling: touch;\n      }\n\n      .nav-scroll::-webkit-scrollbar {\n        display: none;\n      }\n\n      .nav-group {\n        flex: 0 0 auto;\n        display: flex;\n        gap: 8px;\n        margin: 0;\n      }\n\n      .nav-group-title {\n        display: none;\n      }\n\n      .nav-item {\n        width: auto;\n        min-height: 42px;\n        margin: 0;\n        padding: 9px 12px;\n        white-space: nowrap;\n        scroll-snap-align: start;\n      }\n\n      .col-4,\n      .col-5,\n      .col-6,\n      .col-7,\n      .col-8 {\n        grid-column: span 12;\n      }\n    }\n\n    @media (max-width: 720px) {\n      :root {\n        --radius-xl: 0px;\n        --radius-lg: 18px;\n        --radius-md: 13px;\n      }\n\n      html,\n      body {\n        width: 100%;\n        height: 100%;\n        overflow: hidden;\n        overscroll-behavior: none;\n      }\n\n      body {\n        font-size: 15px;\n        background:\n          radial-gradient(circle at 18% 8%, rgba(199, 163, 255, 0.34), transparent 34%),\n          linear-gradient(180deg, #fbf8ff 0%, #f6efff 100%);\n      }\n\n      button,\n      input,\n      select,\n      textarea {\n        font-size: 15px;\n      }\n\n      .btn,\n      .nav-item,\n      .open-main {\n        min-height: 44px;\n        touch-action: manipulation;\n      }\n\n      .welcome-card {\n        width: calc(100vw - 28px);\n        padding: 28px 18px;\n        border-radius: 26px;\n      }\n\n      .quick-panel {\n        left: max(12px, env(safe-area-inset-left));\n        right: max(12px, env(safe-area-inset-right));\n        bottom: calc(88px + env(safe-area-inset-bottom));\n        width: auto;\n        max-height: min(72vh, 520px);\n        overflow: auto;\n        padding: 16px;\n        border-radius: 24px;\n      }\n\n      .quick-head {\n        align-items: flex-start;\n      }\n\n      .quick-stats {\n        gap: 8px;\n      }\n\n      .stat {\n        padding: 10px 6px;\n      }\n\n      .quick-actions {\n        grid-template-columns: 1fr;\n      }\n\n      .float-ball {\n        right: max(14px, env(safe-area-inset-right));\n        bottom: max(14px, env(safe-area-inset-bottom));\n        width: 62px;\n        height: 62px;\n        box-shadow: 0 14px 34px rgba(101, 63, 209, 0.34);\n      }\n\n      .float-ball .logo {\n        width: 42px;\n        height: 42px;\n        font-size: 19px;\n      }\n\n      .app-shell {\n        inset: 0;\n        grid-template-columns: minmax(0, 1fr);\n        width: 100vw;\n        height: 100dvh;\n        max-height: 100dvh;\n        overflow: hidden;\n        border: 0;\n        border-radius: 0;\n        grid-template-rows: auto minmax(0, 1fr);\n        background: rgba(255, 255, 255, 0.78);\n      }\n\n      .sidebar {\n        gap: 10px;\n        min-width: 0;\n        width: 100%;\n        overflow: hidden;\n        min-height: 0;\n        padding: calc(10px + env(safe-area-inset-top)) 12px 10px;\n        background:\n          linear-gradient(180deg, rgba(255,255,255,0.72), rgba(255,255,255,0.42)),\n          linear-gradient(135deg, var(--primary-soft), rgba(255,255,255,0.74));\n      }\n\n      .brand {\n        gap: 10px;\n        padding: 0 2px 10px;\n      }\n\n      .brand-icon {\n        width: 42px;\n        height: 42px;\n        border-radius: 15px;\n      }\n\n      .brand h1 {\n        font-size: 21px;\n      }\n\n      .brand p {\n        font-size: 11px;\n      }\n\n      .sidebar-foot {\n        display: flex;\n        gap: 8px;\n        overflow-x: auto;\n        padding-bottom: 2px;\n      }\n\n      .sidebar-foot .btn {\n        flex: 0 0 auto;\n        min-height: 40px;\n        padding: 8px 12px;\n        font-size: 13px;\n      }\n\n      .content {\n        min-height: 0;\n        min-width: 0;\n        width: 100%;\n        overflow: hidden;\n      }\n\n      .topbar {\n        align-items: stretch;\n        min-width: 0;\n        width: 100%;\n        flex-direction: column;\n        gap: 10px;\n        padding: 12px 14px;\n        background: rgba(255, 255, 255, 0.62);\n      }\n\n      .panel-title h2 {\n        font-size: 20px;\n        line-height: 1.25;\n      }\n\n      .panel-title p {\n        font-size: 12px;\n        line-height: 1.55;\n      }\n\n      .top-actions {\n        justify-content: flex-start;\n        gap: 8px;\n        overflow-x: auto;\n        flex-wrap: nowrap;\n        padding-bottom: 2px;\n        -webkit-overflow-scrolling: touch;\n      }\n\n      .top-actions .chip,\n      .top-actions .btn {\n        flex: 0 0 auto;\n      }\n\n      .main {\n        flex: 1;\n        min-width: 0;\n        width: 100%;\n        min-height: 0;\n        overflow: auto;\n        padding: 12px 12px calc(86px + env(safe-area-inset-bottom));\n        -webkit-overflow-scrolling: touch;\n      }\n\n      .grid {\n        grid-template-columns: 1fr;\n        gap: 12px;\n      }\n\n      .col-4,\n      .col-5,\n      .col-6,\n      .col-7,\n      .col-8,\n      .col-12 {\n        grid-column: 1 / -1;\n      }\n\n      .card {\n        padding: 14px;\n        border-radius: 18px;\n        box-shadow: 0 8px 22px rgba(80, 59, 120, 0.07);\n      }\n\n      .card h3 {\n        font-size: 16px;\n      }\n\n      .person-card,\n      .entry-card {\n        align-items: flex-start;\n        padding: 11px;\n        border-radius: 16px;\n      }\n\n      .person-card .btn,\n      .entry-card .btn {\n        min-height: 38px;\n        padding: 7px 10px;\n        font-size: 13px;\n      }\n\n      .avatar {\n        flex-basis: 48px;\n        width: 48px;\n        height: 48px;\n        border-radius: 17px;\n      }\n\n      .q-card {\n        min-height: 286px;\n      }\n\n      .q-figure {\n        width: 138px;\n        height: 162px;\n        margin: 4px 0 12px;\n        border-width: 6px;\n      }\n\n      .q-placeholder {\n        font-size: 58px;\n      }\n\n      .bubble {\n        top: 62px;\n        right: 12px;\n        max-width: 172px;\n        font-size: 12px;\n      }\n\n      input,\n      select,\n      textarea {\n        min-height: 44px;\n        padding: 11px 12px;\n        border-radius: 13px;\n      }\n\n      textarea {\n        min-height: 128px;\n      }\n\n      .toolbar {\n        gap: 8px;\n        overflow-x: auto;\n        flex-wrap: nowrap;\n        padding-bottom: 2px;\n      }\n\n      .toolbar .btn,\n      .toolbar .chip {\n        flex: 0 0 auto;\n      }\n\n      .theme-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .chat-log {\n        min-height: 260px;\n        max-height: 46dvh;\n      }\n\n      .msg {\n        max-width: 88%;\n        font-size: 14px;\n      }\n\n      .modal-mask {\n        align-items: end;\n        padding: 0;\n      }\n\n      .modal {\n        width: 100vw;\n        max-height: 88dvh;\n        padding: 18px 14px calc(18px + env(safe-area-inset-bottom));\n        border-radius: 24px 24px 0 0;\n        border-left: 0;\n        border-right: 0;\n        border-bottom: 0;\n      }\n\n      .modal-head {\n        align-items: flex-start;\n        gap: 10px;\n      }\n\n      .modal-head h2 {\n        font-size: 20px;\n      }\n\n      .save-state {\n        left: 12px;\n        right: 12px;\n        bottom: calc(12px + env(safe-area-inset-bottom));\n        text-align: center;\n      }\n\n      .mobile-topbar {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        gap: 10px;\n        padding: calc(10px + env(safe-area-inset-top)) 14px 10px;\n        background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n        color: white;\n        min-height: 52px;\n      }\n\n      .mobile-title {\n        font-size: 18px;\n        font-weight: 800;\n        letter-spacing: 0.08em;\n        flex: 1;\n        text-align: center;\n      }\n\n      .menu-btn {\n        display: inline-flex;\n        flex-direction: column;\n        justify-content: center;\n        gap: 4px;\n        width: 42px;\n        height: 42px;\n        padding: 0;\n        border: 0;\n        border-radius: 13px;\n        background: rgba(255,255,255,0.18);\n        color: white;\n        font-size: 18px;\n        line-height: 1;\n        touch-action: manipulation;\n      }\n\n      .menu-btn.ghost {\n        background: transparent;\n        font-size: 20px;\n      }\n\n      .menu-icon {\n        display: block;\n        width: 18px;\n        height: 2px;\n        margin: 0 auto;\n        background: white;\n        border-radius: 2px;\n      }\n\n      .drawer-mask {\n        position: fixed;\n        inset: 0;\n        z-index: 40;\n        display: none;\n        background: rgba(20, 12, 40, 0.5);\n        backdrop-filter: blur(2px);\n      }\n\n      .drawer-mask.show {\n        display: block;\n      }\n\n      .sidebar {\n        position: fixed;\n        top: 0;\n        left: 0;\n        bottom: 0;\n        z-index: 50;\n        width: min(82vw, 320px);\n        max-width: 320px;\n        height: 100dvh;\n        max-height: 100dvh;\n        transform: translateX(-100%);\n        transition: transform 0.28s ease;\n        background:\n          linear-gradient(180deg, rgba(30,18,55,0.96), rgba(40,24,75,0.96)),\n          linear-gradient(160deg, var(--primary-dark), rgba(20,12,40,0.98));\n        color: rgba(255,255,255,0.92);\n        border-right: 0;\n        padding: calc(16px + env(safe-area-inset-top)) 14px calc(16px + env(safe-area-inset-bottom));\n        overflow-y: auto;\n        gap: 12px;\n      }\n\n      .sidebar.show {\n        transform: translateX(0);\n      }\n\n      .drawer-close {\n        position: absolute;\n        top: 14px;\n        right: 12px;\n        width: 34px;\n        height: 34px;\n        border: 0;\n        border-radius: 12px;\n        background: rgba(255,255,255,0.14);\n        color: white;\n        font-size: 15px;\n      }\n\n      .brand {\n        padding: 6px 4px 12px;\n        border-bottom: 1px solid rgba(255,255,255,0.12);\n      }\n\n      .brand-icon {\n        background: linear-gradient(135deg, var(--accent), var(--primary));\n      }\n\n      .brand h1 {\n        color: white;\n      }\n\n      .brand p {\n        color: rgba(255,255,255,0.62);\n      }\n\n      .nav-scroll {\n        flex: 1;\n        display: flex;\n        flex-direction: column;\n        gap: 6px;\n        overflow-y: auto;\n        padding: 4px 0;\n      }\n\n      .nav-group {\n        display: flex;\n        flex-direction: column;\n        gap: 4px;\n        margin: 0 0 6px;\n      }\n\n      .nav-group-title {\n        display: block;\n        margin: 10px 6px 6px;\n        color: rgba(255,255,255,0.5);\n        font-size: 11px;\n        letter-spacing: 0.06em;\n      }\n\n      .nav-item {\n        width: 100%;\n        min-height: 46px;\n        margin: 0;\n        padding: 12px 14px;\n        border-radius: 14px;\n        color: rgba(255,255,255,0.86);\n        background: rgba(255,255,255,0.06);\n        font-size: 15px;\n        white-space: normal;\n      }\n\n      .nav-item.active {\n        color: white;\n        background: linear-gradient(135deg, var(--primary), var(--primary-dark));\n        box-shadow: 0 8px 20px rgba(101,63,209,0.34);\n      }\n\n      .sidebar-foot {\n        display: flex;\n        flex-direction: column;\n        gap: 8px;\n        margin-top: 8px;\n      }\n\n      .sidebar-foot .btn {\n        width: 100%;\n        min-height: 44px;\n      }\n\n      .content {\n        width: 100%;\n        min-width: 0;\n      }\n\n      .topbar {\n        display: none;\n      }\n\n      .main {\n        flex: 1;\n        min-height: 0;\n        overflow: auto;\n        padding: 12px 12px calc(90px + env(safe-area-inset-bottom));\n        -webkit-overflow-scrolling: touch;\n      }\n    }\n\n    /* 注入组件模式：不污染宿主 WorkBuddy 页面 */\n    html,\n    body {\n      background: transparent !important;\n    }\n\n    .welcome {\n      display: none !important;\n    }\n\n  </style>\n</head>\n<body>\n  <div class=\"ambient\" aria-hidden=\"true\">\n    <i class=\"star\"></i>\n    <i class=\"star\"></i>\n    <i class=\"star\"></i>\n    <i class=\"star\"></i>\n    <i class=\"star\"></i>\n  </div>\n\n  <main class=\"welcome\" id=\"welcome\">\n    <section class=\"welcome-card\">\n      <h1>星寄</h1>\n      <p>一个稳定的追星悬浮球工作台。它会保存人物档案、主题、悬浮球位置、日记、提醒和 AI 问答记录；再次打开时，会恢复到你上次离开的状态。</p>\n      <button class=\"open-main\" id=\"welcomeOpen\">进入星寄工作台</button>\n    </section>\n  </main>\n\n  <section class=\"quick-panel\" id=\"quickPanel\" aria-label=\"星寄快捷面板\"></section>\n\n  <section class=\"app-shell\" id=\"appShell\" aria-label=\"星寄完整工作台\">\n    <header class=\"mobile-topbar\">\n      <button class=\"menu-btn\" data-action=\"openDrawer\" aria-label=\"打开导航菜单\">\n        <span class=\"menu-icon\"></span>\n        <span class=\"menu-icon\"></span>\n        <span class=\"menu-icon\"></span>\n      </button>\n      <span class=\"mobile-title\" id=\"mobileTitle\">星寄</span>\n      <button class=\"menu-btn ghost\" data-action=\"openThemes\" aria-label=\"配色模板\">◑</button>\n    </header>\n    <div class=\"drawer-mask\" id=\"drawerMask\"></div>\n    <aside class=\"sidebar\">\n      <button class=\"drawer-close\" data-action=\"closeDrawer\" aria-label=\"关闭导航菜单\">✕</button>\n      <div class=\"brand\">\n        <div class=\"brand-icon\">星</div>\n        <div>\n          <h1>星寄</h1>\n          <p>追星悬浮球 APP</p>\n        </div>\n      </div>\n\n      <div class=\"nav-scroll\" id=\"nav\"></div>\n\n      <div class=\"sidebar-foot\">\n        <button class=\"btn ghost\" data-action=\"openThemes\">配色模板库</button>\n        <button class=\"btn line\" data-action=\"minimize\">最小化为悬浮球</button>\n      </div>\n    </aside>\n\n    <section class=\"content\">\n      <header class=\"topbar\">\n        <div class=\"panel-title\" id=\"panelTitle\"></div>\n        <div class=\"top-actions\">\n          <span class=\"chip\" id=\"currentPersonChip\">当前守护：未选择</span>\n          <button class=\"btn ghost\" data-action=\"openThemes\">配色模板库</button>\n          <button class=\"btn line\" data-action=\"exportData\">导出备份</button>\n        </div>\n      </header>\n      <div class=\"main\" id=\"main\"></div>\n    </section>\n  </section>\n\n  <button class=\"float-ball\" id=\"floatBall\" aria-label=\"打开星寄悬浮球\">\n    <span class=\"logo\">星</span>\n    <span class=\"badge\" id=\"badge\"></span>\n  </button>\n\n  <section class=\"modal-mask\" id=\"modalMask\">\n    <div class=\"modal\">\n      <div class=\"modal-head\">\n        <h2 id=\"modalTitle\">设置</h2>\n        <button class=\"btn line\" data-action=\"closeModal\">关闭</button>\n      </div>\n      <div id=\"modalBody\"></div>\n    </div>\n  </section>\n\n  <div class=\"save-state\" id=\"saveState\">已自动保存</div>\n\n  <script>\n    const STORAGE_KEY = \"xingji.workbuddy.app.v1\";\n\n    const themes = {\n      purple: { name: \"默认紫色系\", primary: \"#8d5cf6\", dark: \"#653fd1\", soft: \"#f2ebff\", accent: \"#c7a3ff\" },\n      macaron: { name: \"马卡龙\", primary: \"#ff9fcf\", dark: \"#d86fa9\", soft: \"#fff0f7\", accent: \"#9ee7dc\" },\n      mono: { name: \"黑白简约\", primary: \"#333333\", dark: \"#111111\", soft: \"#f4f4f4\", accent: \"#cfcfcf\" },\n      morandi: { name: \"莫兰迪\", primary: \"#8aa399\", dark: \"#667a72\", soft: \"#eef3f0\", accent: \"#d8c8b8\" },\n      warm: { name: \"暖色\", primary: \"#ff8a5b\", dark: \"#d85f33\", soft: \"#fff1ea\", accent: \"#ffd166\" },\n      cool: { name: \"冷色\", primary: \"#4f8cff\", dark: \"#2d5fd1\", soft: \"#edf4ff\", accent: \"#8be9fd\" }\n    };\n\n    const navGroups = [\n      {\n        title: \"明星人物库\",\n        items: [\n          [\"people\", \"人物库首页\"],\n          [\"actors\", \"演员合集库\"],\n          [\"singers\", \"歌手合集库\"],\n          [\"customPeople\", \"自定义人物库\"],\n          [\"newPerson\", \"新增人物档案\"]\n        ]\n      },\n      {\n        title: \"行程日志\",\n        items: [\n          [\"feed\", \"全网多平台实时动态\"],\n          [\"calendar\", \"官方行程时间轴日历\"],\n          [\"favorites\", \"收藏动态归档库\"],\n          [\"scheduleReminder\", \"行程一键创建提醒\"]\n        ]\n      },\n      {\n        title: \"日记提醒 & AI 问答\",\n        items: [\n          [\"diary\", \"个人追星日记本\"],\n          [\"reminders\", \"定时提醒管理列表\"],\n          [\"ai\", \"AI 智能问答对话窗\"],\n          [\"aiHistory\", \"AI 历史问答记录库\"]\n        ]\n      }\n    ];\n\n    const defaultState = {\n      view: \"people\",\n      shell: \"open\",\n      quickOpen: false,\n      firstRunDone: false,\n      currentPersonId: \"demo-zi\",\n      themeId: \"purple\",\n      customTheme: null,\n      ball: { x: null, y: null },\n      people: [\n        {\n          id: \"demo-zi\",\n          name: \"示例艺人\",\n          type: \"演员\",\n          circle: \"影视剧演员\",\n          color: \"#8d5cf6\",\n          quote: \"今天也要把喜欢变成认真生活的力量。\",\n          image: \"\"\n        }\n      ],\n      activities: [\n        { id: uid(), personId: \"demo-zi\", platform: \"微博\", type: \"官宣\", title: \"新剧开机公开动态\", content: \"示例动态：这里可归档公开官方资讯，后续可接入平台同步。\", date: today(), favorite: true },\n        { id: uid(), personId: \"demo-zi\", platform: \"央视新闻\", type: \"晚会\", title: \"晚会节目单更新\", content: \"示例动态：正式公开活动可沉淀到行程日历。\", date: today(), favorite: false }\n      ],\n      schedules: [\n        { id: uid(), personId: \"demo-zi\", title: \"直播预告\", date: today(), time: \"20:00\", type: \"直播\", important: true }\n      ],\n      diaries: [],\n      reminders: [],\n      chats: [\n        { id: uid(), personId: \"demo-zi\", role: \"ai\", text: \"你好，我是星寄 AI 助手。你可以让我帮你写追星文案、整理行程、规划预算或记录今天的心情。\", time: nowText() }\n      ]\n    };\n\n    let state = loadState();\n    let saveTimer = null;\n    let dragged = false;\n\n    const $ = (selector) => document.querySelector(selector);\n    const root = document.documentElement;\n    const appShell = $(\"#appShell\");\n      const drawerMask = $(\"#drawerMask\");\n    const floatBall = $(\"#floatBall\");\n    const quickPanel = $(\"#quickPanel\");\n    const welcome = $(\"#welcome\");\n    const main = $(\"#main\");\n    const nav = $(\"#nav\");\n    const panelTitle = $(\"#panelTitle\");\n    const currentPersonChip = $(\"#currentPersonChip\");\n    const badge = $(\"#badge\");\n    const modalMask = $(\"#modalMask\");\n    const modalTitle = $(\"#modalTitle\");\n    const modalBody = $(\"#modalBody\");\n    const saveState = $(\"#saveState\");\n\n    function init() {\n      applyTheme();\n      restoreBallPosition();\n      renderNav();\n      render();\n      renderQuickPanel();\n      bindGlobalEvents();\n      state.shell = \"open\";\n      state.firstRunDone = true;\n      save();\n      applyShellState();\n      autoPersistOnExit();\n      showRestoreToast();\n    }\n\n    function bindGlobalEvents() {\n      $(\"#welcomeOpen\").addEventListener(\"click\", () => openShell(\"people\"));\n      drawerMask.addEventListener(\"click\", () => {\n        drawerMask.classList.remove(\"show\");\n        const sb = document.querySelector(\".sidebar\");\n        if (sb) sb.classList.remove(\"show\");\n      });\n      window.addEventListener(\"resize\", keepBallInViewport);\n      floatBall.addEventListener(\"dblclick\", () => {\n        openShell(state.view || \"people\");\n      });\n      floatBall.addEventListener(\"click\", () => {\n        if (dragged) {\n          dragged = false;\n          return;\n        }\n        state.quickOpen = !state.quickOpen;\n        state.shell = state.shell === \"open\" ? \"open\" : \"quick\";\n        save();\n        applyShellState();\n      });\n      makeBallDraggable();\n\n      document.body.addEventListener(\"click\", (event) => {\n        const action = event.target.closest(\"[data-action]\")?.dataset.action;\n        if (!action) return;\n        actions[action](event);\n      });\n\n      document.body.addEventListener(\"submit\", (event) => {\n        event.preventDefault();\n        const form = event.target;\n        if (form.dataset.form && formHandlers[form.dataset.form]) {\n          formHandlers[form.dataset.form](new FormData(form), form);\n        }\n      });\n\n      document.body.addEventListener(\"change\", (event) => {\n        const target = event.target;\n        if (target.dataset.bind === \"currentPerson\") {\n          state.currentPersonId = target.value;\n          save();\n          applyTheme();\n          render();\n          renderQuickPanel();\n        }\n      });\n    }\n\n    const actions = {\n      nav(event) {\n        const view = event.target.closest(\"[data-view]\").dataset.view;\n        openShell(view);\n        drawerMask.classList.remove(\"show\");\n        const sb = document.querySelector(\".sidebar\");\n        if (sb) sb.classList.remove(\"show\");\n      },\n      minimize() {\n        state.shell = \"closed\";\n        state.quickOpen = false;\n        save();\n        applyShellState();\n      },\n      openThemes() {\n        openThemesModal();\n      },\n      closeModal() {\n        modalMask.classList.remove(\"show\");\n      },\n      openDrawer() {\n        appShell.classList.add(\"show\");\n        const sb = document.querySelector(\".sidebar\");\n        if (sb) sb.classList.add(\"show\");\n        drawerMask.classList.add(\"show\");\n      },\n      closeDrawer() {\n        drawerMask.classList.remove(\"show\");\n        const sb = document.querySelector(\".sidebar\");\n        if (sb) sb.classList.remove(\"show\");\n      },\n      exportData() {\n        const blob = new Blob([JSON.stringify(state, null, 2)], { type: \"application/json\" });\n        const url = URL.createObjectURL(blob);\n        const a = document.createElement(\"a\");\n        a.href = url;\n        a.download = `星寄数据备份-${today()}.json`;\n        a.click();\n        URL.revokeObjectURL(url);\n      },\n      resetDemo() {\n        if (!confirm(\"确定要重置星寄数据吗？当前本地保存内容会被清空。\")) return;\n        localStorage.removeItem(STORAGE_KEY);\n        state = structuredClone(defaultState);\n        save();\n        applyTheme();\n        renderNav();\n        render();\n        renderQuickPanel();\n        applyShellState();\n      },\n      selectPerson(event) {\n        const id = event.target.closest(\"[data-person-id]\").dataset.personId;\n        state.currentPersonId = id;\n        save();\n        applyTheme();\n        render();\n        renderQuickPanel();\n      },\n      deletePerson(event) {\n        const id = event.target.closest(\"[data-person-id]\").dataset.personId;\n        if (state.people.length === 1) {\n          alert(\"至少保留一个人物档案。\");\n          return;\n        }\n        state.people = state.people.filter((item) => item.id !== id);\n        if (state.currentPersonId === id) state.currentPersonId = state.people[0]?.id || null;\n        save();\n        applyTheme();\n        render();\n        renderQuickPanel();\n      },\n      toggleFavorite(event) {\n        const id = event.target.closest(\"[data-activity-id]\").dataset.activityId;\n        const activity = state.activities.find((item) => item.id === id);\n        if (activity) activity.favorite = !activity.favorite;\n        save();\n        render();\n        renderQuickPanel();\n      },\n      scheduleToReminder(event) {\n        const id = event.target.closest(\"[data-schedule-id]\").dataset.scheduleId;\n        const schedule = state.schedules.find((item) => item.id === id);\n        if (!schedule) return;\n        state.reminders.push({\n          id: uid(),\n          personId: schedule.personId,\n          title: schedule.title,\n          date: schedule.date,\n          time: schedule.time,\n          advance: \"30 分钟\",\n          source: \"行程同步\",\n          enabled: true\n        });\n        save();\n        state.view = \"reminders\";\n        renderNav();\n        render();\n        renderQuickPanel();\n      },\n      toggleReminder(event) {\n        const id = event.target.closest(\"[data-reminder-id]\").dataset.reminderId;\n        const reminder = state.reminders.find((item) => item.id === id);\n        if (reminder) reminder.enabled = !reminder.enabled;\n        save();\n        render();\n        renderQuickPanel();\n      },\n      deleteEntry(event) {\n        const { collection, id } = event.target.closest(\"[data-entry]\").dataset;\n        state[collection] = state[collection].filter((item) => item.id !== id);\n        save();\n        render();\n        renderQuickPanel();\n      },\n      showBubble() {\n        const bubble = $(\".bubble\");\n        if (!bubble) return;\n        bubble.classList.add(\"show\");\n        setTimeout(() => bubble.classList.remove(\"show\"), 2600);\n      },\n      quickDiary() {\n        openShell(\"diary\");\n      },\n      quickAI() {\n        openShell(\"ai\");\n      },\n      quickPerson() {\n        openShell(\"people\");\n      },\n      quickWorkspace() {\n        openShell(state.view || \"people\");\n      },\n      applyTheme(event) {\n        const id = event.target.closest(\"[data-theme-id]\").dataset.themeId;\n        state.themeId = id;\n        state.customTheme = null;\n        save();\n        applyTheme();\n        render();\n        renderQuickPanel();\n      }\n    };\n\n    const formHandlers = {\n      person(data, form) {\n        const imageFile = data.get(\"image\");\n        const person = {\n          id: uid(),\n          name: data.get(\"name\").trim(),\n          type: data.get(\"type\"),\n          circle: data.get(\"circle\").trim() || data.get(\"type\"),\n          color: data.get(\"color\") || \"#8d5cf6\",\n          quote: data.get(\"quote\").trim() || \"今天也要把喜欢变成认真生活的力量。\",\n          image: \"\"\n        };\n        if (!person.name) return alert(\"请填写艺人姓名。\");\n        const finish = () => {\n          state.people.push(person);\n          state.currentPersonId = person.id;\n          state.view = \"people\";\n          save();\n          applyTheme();\n          renderNav();\n          render();\n          renderQuickPanel();\n          form.reset();\n        };\n        if (imageFile && imageFile.size) {\n          const reader = new FileReader();\n          reader.onload = () => {\n            person.image = reader.result;\n            finish();\n          };\n          reader.readAsDataURL(imageFile);\n        } else {\n          finish();\n        }\n      },\n      activity(data, form) {\n        state.activities.unshift({\n          id: uid(),\n          personId: data.get(\"personId\") || state.currentPersonId,\n          platform: data.get(\"platform\"),\n          type: data.get(\"type\"),\n          title: data.get(\"title\").trim(),\n          content: data.get(\"content\").trim(),\n          date: data.get(\"date\") || today(),\n          favorite: false\n        });\n        save();\n        form.reset();\n        render();\n        renderQuickPanel();\n      },\n      schedule(data, form) {\n        state.schedules.push({\n          id: uid(),\n          personId: data.get(\"personId\") || state.currentPersonId,\n          title: data.get(\"title\").trim(),\n          date: data.get(\"date\") || today(),\n          time: data.get(\"time\") || \"20:00\",\n          type: data.get(\"type\") || \"行程\",\n          important: data.get(\"important\") === \"on\"\n        });\n        save();\n        form.reset();\n        render();\n        renderQuickPanel();\n      },\n      diary(data, form) {\n        state.diaries.unshift({\n          id: uid(),\n          personId: data.get(\"personId\") || state.currentPersonId,\n          title: data.get(\"title\").trim() || \"未命名日记\",\n          mood: data.get(\"mood\"),\n          tags: data.get(\"tags\").trim(),\n          content: data.get(\"content\").trim(),\n          date: data.get(\"date\") || today(),\n          createdAt: nowText()\n        });\n        save();\n        form.reset();\n        render();\n        renderQuickPanel();\n      },\n      reminder(data, form) {\n        state.reminders.push({\n          id: uid(),\n          personId: data.get(\"personId\") || state.currentPersonId,\n          title: data.get(\"title\").trim(),\n          date: data.get(\"date\") || today(),\n          time: data.get(\"time\") || \"09:00\",\n          advance: data.get(\"advance\"),\n          source: \"自建提醒\",\n          enabled: true\n        });\n        save();\n        form.reset();\n        render();\n        renderQuickPanel();\n      },\n      chat(data, form) {\n        const text = data.get(\"text\").trim();\n        if (!text) return;\n        const personId = state.currentPersonId;\n        state.chats.push({ id: uid(), personId, role: \"user\", text, time: nowText() });\n        state.chats.push({ id: uid(), personId, role: \"ai\", text: makeAIReply(text), time: nowText() });\n        save();\n        form.reset();\n        render();\n        renderQuickPanel();\n      },\n      customTheme(data) {\n        state.customTheme = {\n          name: \"自定义主题\",\n          primary: data.get(\"primary\"),\n          dark: data.get(\"dark\"),\n          soft: data.get(\"soft\"),\n          accent: data.get(\"accent\")\n        };\n        state.themeId = \"custom\";\n        save();\n        applyTheme();\n        render();\n        renderQuickPanel();\n        openThemesModal();\n      }\n    };\n\n    function renderNav() {\n      nav.innerHTML = navGroups.map(group => `\n        <div class=\"nav-group\">\n          <p class=\"nav-group-title\">${group.title}</p>\n          ${group.items.map(([view, label]) => `\n            <button class=\"nav-item ${state.view === view ? \"active\" : \"\"}\" data-action=\"nav\" data-view=\"${view}\">\n              <span>${iconFor(view)}</span><span>${label}</span>\n            </button>\n          `).join(\"\")}\n        </div>\n      `).join(\"\");\n    }\n\n    function render() {\n      const title = titleFor(state.view);\n      const person = currentPerson();\n      panelTitle.innerHTML = `<h2>${title}</h2><p>${subtitleFor(state.view)}</p>`;\n      currentPersonChip.textContent = `当前守护：${person ? person.name : \"未选择\"}`;\n      main.innerHTML = views[state.view] ? views[state.view]() : views.people();\n      const mobileTitle = document.getElementById(\"mobileTitle\");\n      if (mobileTitle) mobileTitle.textContent = title;\n      updateBadge();\n      renderNav();\n    }\n\n    const views = {\n      people() {\n        const person = currentPerson();\n        return `\n          <div class=\"grid\">\n            <section class=\"card col-7\">\n              <h3>人物档案</h3>\n              <div class=\"toolbar\">\n                <button class=\"btn ghost\" onclick=\"document.querySelector('[data-view=newPerson]').click()\">新增人物档案</button>\n                <button class=\"btn line\" data-action=\"resetDemo\">重置本地数据</button>\n              </div>\n              <div class=\"people-list\">\n                ${state.people.map(personCard).join(\"\")}\n              </div>\n            </section>\n            <section class=\"card col-5 q-card\">\n              ${qFigure(person)}\n            </section>\n            <section class=\"card col-12\">\n              <h3>人物切换后的联动效果</h3>\n              <p style=\"line-height:1.8;color:var(--muted);margin:0\">右侧全部页面会跟随当前人物的应援色更新背景、按钮、卡片边框和 Q 版形象。日记、提醒、收藏动态和 AI 对话仍按人物独立保存，切换人物不会覆盖原有资料。</p>\n            </section>\n          </div>\n        `;\n      },\n      actors() {\n        return peopleByType(\"演员\", \"演员合集库\");\n      },\n      singers() {\n        return peopleByType(\"歌手\", \"歌手合集库\");\n      },\n      customPeople() {\n        return peopleByType(\"自定义人物\", \"自定义人物库\");\n      },\n      newPerson() {\n        return `\n          <div class=\"grid\">\n            <section class=\"card col-7\">\n              <h3>新增人物档案</h3>\n              <form class=\"form\" data-form=\"person\">\n                <div class=\"field\"><label>艺人姓名</label><input name=\"name\" placeholder=\"例如：某某艺人\" required></div>\n                <div class=\"field\"><label>身份分类</label><select name=\"type\"><option>演员</option><option>歌手</option><option>自定义人物</option></select></div>\n                <div class=\"field\"><label>所属圈层</label><input name=\"circle\" placeholder=\"影视剧演员 / 流行歌手 / 自定义对象\"></div>\n                <div class=\"field\"><label>应援色</label><input name=\"color\" type=\"color\" value=\"#8d5cf6\"></div>\n                <div class=\"field\"><label>Q 版图片</label><input name=\"image\" type=\"file\" accept=\"image/*\"></div>\n                <div class=\"field\"><label>点击气泡文案</label><textarea name=\"quote\" placeholder=\"写一句应援文案、暖心短句或人物语录\"></textarea></div>\n                <button class=\"btn\" type=\"submit\">保存人物档案</button>\n              </form>\n            </section>\n            <section class=\"card col-5\">\n              <h3>保存说明</h3>\n              <p style=\"line-height:1.8;color:var(--muted)\">提交后人物会自动归类保存，系统会把该人物设为当前守护对象，并立刻使用 TA 的应援色刷新界面风格。图片会以本地数据形式保存，适合原型和个人使用。</p>\n            </section>\n          </div>\n        `;\n      },\n      feed() {\n        return `\n          <div class=\"grid\">\n            <section class=\"card col-5\">\n              <h3>手动添加公开动态</h3>\n              <form class=\"form\" data-form=\"activity\">\n                ${personSelect()}\n                <div class=\"field\"><label>平台</label><select name=\"platform\"><option>微博</option><option>抖音</option><option>小红书</option><option>快手</option><option>播客</option><option>央视新闻</option></select></div>\n                <div class=\"field\"><label>动态类型</label><select name=\"type\"><option>发文</option><option>直播</option><option>商务官宣</option><option>活动路透</option><option>晚会</option><option>节目上线</option></select></div>\n                <div class=\"field\"><label>标题</label><input name=\"title\" required placeholder=\"例如：新综艺官宣\"></div>\n                <div class=\"field\"><label>日期</label><input name=\"date\" type=\"date\" value=\"${today()}\"></div>\n                <div class=\"field\"><label>内容</label><textarea name=\"content\" placeholder=\"粘贴或记录公开动态摘要\"></textarea></div>\n                <button class=\"btn\" type=\"submit\">加入动态信息流</button>\n              </form>\n            </section>\n            <section class=\"card col-7\">\n              <h3>全网多平台实时动态</h3>\n              ${activityList(currentActivities())}\n            </section>\n          </div>\n        `;\n      },\n      calendar() {\n        return `\n          <div class=\"grid\">\n            <section class=\"card col-5\">\n              <h3>新增官方行程</h3>\n              <form class=\"form\" data-form=\"schedule\">\n                ${personSelect()}\n                <div class=\"field\"><label>行程标题</label><input name=\"title\" required placeholder=\"例如：演唱会 / 直播 / 红毯\"></div>\n                <div class=\"field\"><label>行程类型</label><input name=\"type\" placeholder=\"拍戏 / 演唱会 / 晚会 / 采访\"></div>\n                <div class=\"field\"><label>日期</label><input name=\"date\" type=\"date\" value=\"${today()}\"></div>\n                <div class=\"field\"><label>时间</label><input name=\"time\" type=\"time\" value=\"20:00\"></div>\n                <label class=\"chip\" style=\"justify-content:flex-start\"><input name=\"important\" type=\"checkbox\" style=\"width:auto\"> 重要行程标星</label>\n                <button class=\"btn\" type=\"submit\">保存到行程日历</button>\n              </form>\n            </section>\n            <section class=\"card col-7\">\n              <h3>官方行程时间轴日历</h3>\n              ${scheduleList(currentSchedules())}\n            </section>\n          </div>\n        `;\n      },\n      favorites() {\n        return `\n          <div class=\"card\">\n            <h3>收藏动态归档库</h3>\n            ${activityList(currentActivities().filter(item => item.favorite))}\n          </div>\n        `;\n      },\n      scheduleReminder() {\n        return `\n          <div class=\"card\">\n            <h3>行程一键创建提醒</h3>\n            <p style=\"color:var(--muted);line-height:1.8\">选择某条行程后，可一键同步到提醒管理列表。第一版会先保存到工作台内部提醒，后续可继续接入 WorkBuddy 的真实提醒能力。</p>\n            ${scheduleList(currentSchedules(), true)}\n          </div>\n        `;\n      },\n      diary() {\n        return `\n          <div class=\"grid\">\n            <section class=\"card col-5\">\n              <h3>写一篇追星日记</h3>\n              <form class=\"form\" data-form=\"diary\">\n                ${personSelect()}\n                <div class=\"field\"><label>日记标题</label><input name=\"title\" placeholder=\"例如：今天看完舞台后的心情\"></div>\n                <div class=\"field\"><label>日期</label><input name=\"date\" type=\"date\" value=\"${today()}\"></div>\n                <div class=\"field\"><label>心情标签</label><select name=\"mood\"><option>开心</option><option>激动</option><option>感动</option><option>治愈</option><option>失落</option></select></div>\n                <div class=\"field\"><label>分类标签</label><input name=\"tags\" placeholder=\"见面记录、观演体验、消费记录\"></div>\n                <div class=\"field\"><label>正文</label><textarea name=\"content\" required placeholder=\"记录追星日常、线下见闻、观影听歌感悟、应援经历\"></textarea></div>\n                <button class=\"btn\" type=\"submit\">保存日记</button>\n              </form>\n            </section>\n            <section class=\"card col-7\">\n              <h3>日记时间线</h3>\n              ${entryList(currentDiaries(), \"diaries\", item => `${item.date}｜${item.mood}｜${item.tags || \"未分类\"}`, item => item.content)}\n            </section>\n          </div>\n        `;\n      },\n      reminders() {\n        return `\n          <div class=\"grid\">\n            <section class=\"card col-5\">\n              <h3>新增提醒</h3>\n              <form class=\"form\" data-form=\"reminder\">\n                ${personSelect()}\n                <div class=\"field\"><label>提醒内容</label><input name=\"title\" required placeholder=\"例如：周边开售 / 会员续费 / 直播开播\"></div>\n                <div class=\"field\"><label>日期</label><input name=\"date\" type=\"date\" value=\"${today()}\"></div>\n                <div class=\"field\"><label>时间</label><input name=\"time\" type=\"time\" value=\"09:00\"></div>\n                <div class=\"field\"><label>提前提醒</label><select name=\"advance\"><option>5 分钟</option><option>15 分钟</option><option>30 分钟</option><option>1 小时</option><option>1 天</option></select></div>\n                <button class=\"btn\" type=\"submit\">保存提醒</button>\n              </form>\n            </section>\n            <section class=\"card col-7\">\n              <h3>定时提醒管理列表</h3>\n              ${reminderList(currentReminders())}\n            </section>\n          </div>\n        `;\n      },\n      ai() {\n        const chats = currentChats();\n        return `\n          <div class=\"card\">\n            <h3>AI 智能问答对话窗</h3>\n            <div class=\"chat\">\n              <div class=\"toolbar\">\n                <button class=\"btn ghost\" onclick=\"document.querySelector('[name=text]').value='帮我写一段温柔的应援文案'\">文案撰写</button>\n                <button class=\"btn ghost\" onclick=\"document.querySelector('[name=text]').value='帮我规划这个月的追星预算'\">预算规划</button>\n                <button class=\"btn ghost\" onclick=\"document.querySelector('[name=text]').value='帮我安排本周追星和生活日程'\">日程安排</button>\n              </div>\n              <div class=\"chat-log\" id=\"chatLog\">\n                ${chats.map(msg => `<div class=\"msg ${msg.role}\">${escapeHTML(msg.text)}<br><small>${msg.time}</small></div>`).join(\"\")}\n              </div>\n              <form class=\"form\" data-form=\"chat\">\n                <div class=\"field\"><label>输入问题</label><textarea name=\"text\" placeholder=\"可以问生活规划、追星文案、预算管理、情绪疏导等\"></textarea></div>\n                <button class=\"btn\" type=\"submit\">发送并保存</button>\n              </form>\n            </div>\n          </div>\n        `;\n      },\n      aiHistory() {\n        return `\n          <div class=\"card\">\n            <h3>AI 历史问答记录库</h3>\n            ${entryList(currentChats(), \"chats\", item => `${personName(item.personId)}｜${item.role === \"user\" ? \"我\" : \"星寄 AI\"}｜${item.time}`, item => item.text)}\n          </div>\n        `;\n      }\n    };\n\n    function peopleByType(type, heading) {\n      const list = state.people.filter(item => item.type === type);\n      return `\n        <div class=\"card\">\n          <h3>${heading}</h3>\n          ${list.length ? `<div class=\"people-list\">${list.map(personCard).join(\"\")}</div>` : `<div class=\"empty\">还没有${type}档案，可以到「新增人物档案」里添加。</div>`}\n        </div>\n      `;\n    }\n\n    function personCard(person) {\n      return `\n        <div class=\"person-card ${state.currentPersonId === person.id ? \"active\" : \"\"}\" data-person-id=\"${person.id}\">\n          <div class=\"avatar\">${person.image ? `<img src=\"${person.image}\" alt=\"${person.name}\">` : person.name.slice(0, 1)}</div>\n          <div class=\"person-meta\">\n            <strong>${escapeHTML(person.name)}</strong>\n            <span>${escapeHTML(person.type)}｜${escapeHTML(person.circle)}｜日记 ${state.diaries.filter(d => d.personId === person.id).length} 篇</span>\n          </div>\n          <i class=\"color-dot\" style=\"background:${person.color}\"></i>\n          <button class=\"btn ghost\" data-action=\"selectPerson\">切换</button>\n          <button class=\"btn line\" data-action=\"deletePerson\">删除</button>\n        </div>\n      `;\n    }\n\n    function qFigure(person) {\n      if (!person) return `<h3>Q 版人物互动</h3><div class=\"empty\">请先新增或选择人物。</div>`;\n      return `\n        <div>\n          <h3>Q 版人物互动</h3>\n          <p style=\"color:var(--muted);line-height:1.8;margin:0 0 12px\">点击形象会弹出你设置的应援气泡。</p>\n        </div>\n        <div class=\"bubble\">${escapeHTML(person.quote)}</div>\n        <div class=\"q-figure\" data-action=\"showBubble\">\n          ${person.image ? `<img src=\"${person.image}\" alt=\"${person.name}\">` : `<span class=\"q-placeholder\">✦</span>`}\n        </div>\n        <div class=\"entry-meta\" style=\"text-align:center\">\n          <strong>${escapeHTML(person.name)}</strong>\n          <span>应援色 ${person.color}</span>\n        </div>\n      `;\n    }\n\n    function activityList(list) {\n      if (!list.length) return `<div class=\"empty\">暂无动态记录。</div>`;\n      return `<div class=\"entry-list\">${list.map(item => `\n        <div class=\"entry-card\" data-activity-id=\"${item.id}\">\n          <div class=\"avatar\">${item.platform.slice(0,1)}</div>\n          <div class=\"entry-meta\">\n            <strong>${escapeHTML(item.title)}</strong>\n            <span>${personName(item.personId)}｜${item.platform}｜${item.type}｜${item.date}</span>\n            <span>${escapeHTML(item.content)}</span>\n          </div>\n          <button class=\"btn ghost\" data-action=\"toggleFavorite\">${item.favorite ? \"已收藏\" : \"收藏\"}</button>\n        </div>\n      `).join(\"\")}</div>`;\n    }\n\n    function scheduleList(list, reminderMode = false) {\n      if (!list.length) return `<div class=\"empty\">暂无行程记录。</div>`;\n      return `<div class=\"entry-list\">${list.map(item => `\n        <div class=\"entry-card\" data-schedule-id=\"${item.id}\">\n          <div class=\"avatar\">${item.important ? \"★\" : \"程\"}</div>\n          <div class=\"entry-meta\">\n            <strong>${escapeHTML(item.title)}</strong>\n            <span>${personName(item.personId)}｜${item.type}｜${item.date} ${item.time}</span>\n          </div>\n          ${reminderMode ? `<button class=\"btn ghost\" data-action=\"scheduleToReminder\">创建提醒</button>` : `<button class=\"btn line\" data-action=\"scheduleToReminder\">同步提醒</button>`}\n        </div>\n      `).join(\"\")}</div>`;\n    }\n\n    function reminderList(list) {\n      if (!list.length) return `<div class=\"empty\">暂无提醒事项。</div>`;\n      return `<div class=\"entry-list\">${list.map(item => `\n        <div class=\"entry-card\" data-reminder-id=\"${item.id}\">\n          <div class=\"avatar\">${item.enabled ? \"铃\" : \"停\"}</div>\n          <div class=\"entry-meta\">\n            <strong>${escapeHTML(item.title)}</strong>\n            <span>${personName(item.personId)}｜${item.source}｜${item.date} ${item.time}｜提前 ${item.advance}</span>\n          </div>\n          <button class=\"btn ghost\" data-action=\"toggleReminder\">${item.enabled ? \"启用中\" : \"已暂停\"}</button>\n        </div>\n      `).join(\"\")}</div>`;\n    }\n\n    function entryList(list, collection, metaFn, contentFn) {\n      if (!list.length) return `<div class=\"empty\">暂无记录。</div>`;\n      return `<div class=\"entry-list\">${list.map(item => `\n        <div class=\"entry-card\" data-entry data-collection=\"${collection}\" data-id=\"${item.id}\">\n          <div class=\"avatar\">${collection === \"diaries\" ? \"记\" : \"AI\"}</div>\n          <div class=\"entry-meta\">\n            <strong>${escapeHTML(item.title || contentFn(item).slice(0, 24) || \"未命名记录\")}</strong>\n            <span>${escapeHTML(metaFn(item))}</span>\n            <span>${escapeHTML(contentFn(item))}</span>\n          </div>\n          <button class=\"btn line\" data-action=\"deleteEntry\">删除</button>\n        </div>\n      `).join(\"\")}</div>`;\n    }\n\n    function renderQuickPanel() {\n      const person = currentPerson();\n      const reminders = currentReminders().filter(item => item.enabled).length;\n      const activities = currentActivities().length;\n      const diaries = currentDiaries().length;\n      quickPanel.innerHTML = `\n        <div class=\"quick-head\">\n          <div>\n            <h2>星寄</h2>\n            <p>当前守护：${person ? escapeHTML(person.name) : \"未选择\"}</p>\n          </div>\n          <span class=\"chip\">悬浮 APP</span>\n        </div>\n        <div class=\"quick-stats\">\n          <div class=\"stat\"><strong>${reminders}</strong><span>提醒</span></div>\n          <div class=\"stat\"><strong>${activities}</strong><span>动态</span></div>\n          <div class=\"stat\"><strong>${diaries}</strong><span>日记</span></div>\n        </div>\n        <div class=\"quick-actions\">\n          <button class=\"btn\" data-action=\"quickWorkspace\">进入工作台</button>\n          <button class=\"btn ghost\" data-action=\"quickDiary\">写日记</button>\n          <button class=\"btn ghost\" data-action=\"quickAI\">问问 AI</button>\n          <button class=\"btn line\" data-action=\"quickPerson\">切换人物</button>\n        </div>\n      `;\n      quickPanel.classList.toggle(\"show\", state.quickOpen && state.shell !== \"open\");\n      updateBadge();\n    }\n\n    function openThemesModal() {\n      modalTitle.textContent = \"配色模板库\";\n      modalBody.innerHTML = `\n        <div class=\"theme-grid\">\n          ${Object.entries(themes).map(([id, theme]) => themeCard(id, theme)).join(\"\")}\n        </div>\n        <hr style=\"border:0;border-top:1px solid var(--line);margin:18px 0\">\n        <form class=\"form\" data-form=\"customTheme\">\n          <h3 style=\"margin:0;color:var(--primary-dark)\">自定义 RGB 配色</h3>\n          <div class=\"grid\">\n            <div class=\"field col-6\"><label>主色</label><input name=\"primary\" type=\"color\" value=\"${activeTheme().primary}\"></div>\n            <div class=\"field col-6\"><label>深色</label><input name=\"dark\" type=\"color\" value=\"${activeTheme().dark}\"></div>\n            <div class=\"field col-6\"><label>浅底色</label><input name=\"soft\" type=\"color\" value=\"${activeTheme().soft}\"></div>\n            <div class=\"field col-6\"><label>点缀色</label><input name=\"accent\" type=\"color\" value=\"${activeTheme().accent}\"></div>\n          </div>\n          <button class=\"btn\" type=\"submit\">保存自定义主题</button>\n        </form>\n      `;\n      modalMask.classList.add(\"show\");\n    }\n\n    function themeCard(id, theme) {\n      return `\n        <button class=\"theme-card\" data-action=\"applyTheme\" data-theme-id=\"${id}\">\n          <div class=\"swatches\">\n            <i style=\"background:${theme.primary}\"></i>\n            <i style=\"background:${theme.dark}\"></i>\n            <i style=\"background:${theme.soft}\"></i>\n            <i style=\"background:${theme.accent}\"></i>\n          </div>\n          <strong>${theme.name}</strong>\n          <span>${state.themeId === id ? \"当前使用\" : \"点击套用\"}</span>\n        </button>\n      `;\n    }\n\n    function openShell(view) {\n      state.view = view || state.view || \"people\";\n      state.shell = \"open\";\n      state.quickOpen = false;\n      save();\n      applyShellState();\n      render();\n      renderQuickPanel();\n    }\n\n    function applyShellState() {\n      const isOpen = state.shell === \"open\";\n      appShell.classList.toggle(\"show\", isOpen);\n      quickPanel.classList.toggle(\"show\", state.quickOpen && !isOpen);\n      welcome.style.display = \"none\";\n      floatBall.classList.toggle(\"show\", true);\n      notifyWidgetHost();\n    }\n\n    function applyTheme() {\n      let theme = activeTheme();\n      const person = currentPerson();\n      if (person && state.themeId !== \"custom\") {\n        theme = { ...theme, primary: person.color, dark: shade(person.color, -24), soft: tint(person.color, 88), accent: tint(person.color, 52) };\n      }\n      root.style.setProperty(\"--primary\", theme.primary);\n      root.style.setProperty(\"--primary-dark\", theme.dark);\n      root.style.setProperty(\"--primary-soft\", theme.soft);\n      root.style.setProperty(\"--accent\", theme.accent);\n    }\n\n    function activeTheme() {\n      if (state.themeId === \"custom\" && state.customTheme) return state.customTheme;\n      return themes[state.themeId] || themes.purple;\n    }\n\n    function makeBallDraggable() {\n      let startX = 0, startY = 0, originX = 0, originY = 0, moving = false;\n      floatBall.addEventListener(\"pointerdown\", (event) => {\n        moving = true;\n        dragged = false;\n        floatBall.setPointerCapture(event.pointerId);\n        const rect = floatBall.getBoundingClientRect();\n        startX = event.clientX;\n        startY = event.clientY;\n        originX = rect.left;\n        originY = rect.top;\n      });\n      floatBall.addEventListener(\"pointermove\", (event) => {\n        if (!moving) return;\n        const dx = event.clientX - startX;\n        const dy = event.clientY - startY;\n        if (Math.abs(dx) + Math.abs(dy) > 8) dragged = true;\n        const nextX = Math.min(window.innerWidth - 78, Math.max(6, originX + dx));\n        const nextY = Math.min(window.innerHeight - 78, Math.max(6, originY + dy));\n        floatBall.style.left = `${nextX}px`;\n        floatBall.style.top = `${nextY}px`;\n        floatBall.style.right = \"auto\";\n        floatBall.style.bottom = \"auto\";\n      });\n      floatBall.addEventListener(\"pointerup\", () => {\n        if (!moving) return;\n        moving = false;\n        const rect = floatBall.getBoundingClientRect();\n        const snapLeft = rect.left < window.innerWidth / 2;\n        const x = snapLeft ? 14 : window.innerWidth - rect.width - 14;\n        floatBall.style.left = `${x}px`;\n        floatBall.style.top = `${rect.top}px`;\n        floatBall.style.right = \"auto\";\n        floatBall.style.bottom = \"auto\";\n        state.ball = { x, y: rect.top };\n        save();\n      });\n    }\n\n    function restoreBallPosition() {\n      if (typeof state.ball.x === \"number\" && typeof state.ball.y === \"number\") {\n        floatBall.style.left = state.ball.x + \"px\";\n        floatBall.style.top = state.ball.y + \"px\";\n        floatBall.style.right = \"auto\";\n        floatBall.style.bottom = \"auto\";\n        keepBallInViewport();\n      }\n    }\n\n    function keepBallInViewport() {\n      const rect = floatBall.getBoundingClientRect();\n      const width = rect.width || 62;\n      const height = rect.height || 62;\n      let x = rect.left;\n      let y = rect.top;\n      if (!Number.isFinite(x) || !Number.isFinite(y)) return;\n      x = Math.min(window.innerWidth - width - 10, Math.max(10, x));\n      y = Math.min(window.innerHeight - height - 10, Math.max(10, y));\n      floatBall.style.left = x + \"px\";\n      floatBall.style.top = y + \"px\";\n      floatBall.style.right = \"auto\";\n      floatBall.style.bottom = \"auto\";\n      state.ball = { x, y };\n    }\n\n    function save() {\n      clearTimeout(saveTimer);\n      saveTimer = setTimeout(() => {\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n        saveState.classList.add(\"show\");\n        setTimeout(() => saveState.classList.remove(\"show\"), 900);\n      }, 80);\n    }\n\n    function loadState() {\n      try {\n        const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));\n        return saved ? mergeState(structuredClone(defaultState), saved) : structuredClone(defaultState);\n      } catch {\n        return structuredClone(defaultState);\n      }\n    }\n\n    function mergeState(base, saved) {\n      return { ...base, ...saved, ball: { ...base.ball, ...(saved.ball || {}) } };\n    }\n\n    function autoPersistOnExit() {\n      const persist = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n      window.addEventListener(\"beforeunload\", persist);\n      window.addEventListener(\"pagehide\", persist);\n      document.addEventListener(\"visibilitychange\", () => {\n        if (document.visibilityState === \"hidden\") persist();\n      });\n      setInterval(persist, 30000);\n    }\n\n    function showRestoreToast() {\n      const person = currentPerson();\n      const name = person ? person.name : \"未选择\";\n      const counts = [\n        `${state.people.length} 位艺人`,\n        `${state.diaries.length} 篇日记`,\n        `${state.reminders.length} 条提醒`,\n        `${state.chats.length} 条对话`\n      ].join(\" · \");\n      saveState.textContent = `已恢复上次数据：${name}｜${counts}`;\n      saveState.classList.add(\"show\");\n      setTimeout(() => {\n        saveState.textContent = \"已自动保存\";\n        saveState.classList.remove(\"show\");\n      }, 3200);\n    }\n\n    function updateBadge() {\n      const count = currentReminders().filter(item => item.enabled).length;\n      badge.textContent = count;\n      badge.classList.toggle(\"show\", count > 0);\n    }\n\n    function currentPerson() {\n      return state.people.find(item => item.id === state.currentPersonId) || state.people[0] || null;\n    }\n\n    function currentActivities() {\n      return state.activities.filter(item => item.personId === state.currentPersonId);\n    }\n\n    function currentSchedules() {\n      return state.schedules.filter(item => item.personId === state.currentPersonId).sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));\n    }\n\n    function currentDiaries() {\n      return state.diaries.filter(item => item.personId === state.currentPersonId);\n    }\n\n    function currentReminders() {\n      return state.reminders.filter(item => item.personId === state.currentPersonId);\n    }\n\n    function currentChats() {\n      return state.chats.filter(item => item.personId === state.currentPersonId);\n    }\n\n    function personSelect() {\n      return `<div class=\"field\"><label>绑定人物</label><select name=\"personId\" data-bind=\"currentPerson\">${state.people.map(item => `<option value=\"${item.id}\" ${item.id === state.currentPersonId ? \"selected\" : \"\"}>${escapeHTML(item.name)}</option>`).join(\"\")}</select></div>`;\n    }\n\n    function personName(id) {\n      return state.people.find(item => item.id === id)?.name || \"未绑定人物\";\n    }\n\n    function titleFor(view) {\n      return navGroups.flatMap(group => group.items).find(([id]) => id === view)?.[1] || \"人物库首页\";\n    }\n\n    function subtitleFor(view) {\n      const map = {\n        people: \"管理全部人物档案，切换 Q 版皮肤与应援色\",\n        actors: \"查看演员分组内的全部收藏对象\",\n        singers: \"查看歌手分组内的全部收藏对象\",\n        customPeople: \"管理自定义公众人物和小众艺人\",\n        newPerson: \"录入艺人信息、Q 版图片和专属应援色\",\n        feed: \"沉淀公开动态，后续可扩展平台自动同步\",\n        calendar: \"按时间线管理正式行程\",\n        favorites: \"归档收藏过的公开资讯\",\n        scheduleReminder: \"把行程同步为提醒事项\",\n        diary: \"记录追星感受、线下见闻和观演体验\",\n        reminders: \"管理行程提醒和自建提醒\",\n        ai: \"内嵌问答窗口，所有对话绑定当前人物\",\n        aiHistory: \"回看和导出历史问答记录\"\n      };\n      return map[view] || \"\";\n    }\n\n    function iconFor(view) {\n      const map = {\n        people: \"✦\", actors: \"演\", singers: \"歌\", customPeople: \"自\", newPerson: \"＋\",\n        feed: \"动\", calendar: \"历\", favorites: \"藏\", scheduleReminder: \"铃\",\n        diary: \"记\", reminders: \"醒\", ai: \"AI\", aiHistory: \"档\"\n      };\n      return map[view] || \"星\";\n    }\n\n    function makeAIReply(text) {\n      if (text.includes(\"预算\")) return \"可以先把追星预算分成固定支出、临时支出和不可动用生活费三类。建议你先写下本月可自由支配金额，再为周边、演出、交通和会员分别设置上限。\";\n      if (text.includes(\"文案\")) return \"可以写成：把星光寄给远方，也把认真生活留给自己。谢谢你在舞台上发光，也提醒我在自己的日子里慢慢变好。\";\n      if (text.includes(\"日程\") || text.includes(\"规划\")) return \"可以把重要行程放在日历里，提前一天设置提醒；当天只保留一到两件追星任务，避免影响休息和工作学习。\";\n      if (text.includes(\"情绪\") || text.includes(\"难过\")) return \"先把情绪写下来，再把能控制的事情列出来。喜欢一个人也应该让你更靠近稳定、温柔和有力量的自己。\";\n      return \"我已经把这次问答保存到当前艺人分组。你可以继续补充目标、时间或预算，我会帮你整理成更清楚的记录。\";\n    }\n\n    function uid() {\n      const random = Math.random().toString(36).slice(2, 10);\n      return `xj-${Date.now().toString(36)}-${random}`;\n    }\n\n    function today() {\n      return new Date().toISOString().slice(0, 10);\n    }\n\n    function nowText() {\n      const date = new Date();\n      return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;\n    }\n\n    function pad(value) {\n      return String(value).padStart(2, \"0\");\n    }\n\n    function escapeHTML(value = \"\") {\n      return String(value)\n        .replaceAll(\"&\", \"&amp;\")\n        .replaceAll(\"<\", \"&lt;\")\n        .replaceAll(\">\", \"&gt;\")\n        .replaceAll('\"', \"&quot;\")\n        .replaceAll(\"'\", \"&#039;\");\n    }\n\n    function tint(hex, amount) {\n      return mix(hex, \"#ffffff\", amount);\n    }\n\n    function shade(hex, amount) {\n      return mix(hex, \"#000000\", Math.abs(amount));\n    }\n\n    function mix(hex, other, amount) {\n      const a = parseHex(hex);\n      const b = parseHex(other);\n      const p = amount / 100;\n      const r = Math.round(a.r + (b.r - a.r) * p);\n      const g = Math.round(a.g + (b.g - a.g) * p);\n      const bl = Math.round(a.b + (b.b - a.b) * p);\n      return `#${[r, g, bl].map(v => v.toString(16).padStart(2, \"0\")).join(\"\")}`;\n    }\n\n    function parseHex(hex) {\n      const clean = hex.replace(\"#\", \"\");\n      return {\n        r: parseInt(clean.slice(0, 2), 16),\n        g: parseInt(clean.slice(2, 4), 16),\n        b: parseInt(clean.slice(4, 6), 16)\n      };\n    }\n\n\n    function notifyWidgetHost() {\n      try {\n        window.parent.postMessage({\n          type: \"xingji-widget-shell\",\n          shell: state.shell,\n          quickOpen: state.quickOpen,\n          view: state.view\n        }, \"*\");\n      } catch (error) {}\n    }\n\n    window.addEventListener(\"message\", (event) => {\n      const data = event.data || {};\n      if (data.type !== \"xingji-widget-command\") return;\n      if (data.command === \"open\") openShell(state.view || \"people\");\n      if (data.command === \"minimize\") {\n        state.shell = \"closed\";\n        state.quickOpen = false;\n        save();\n        applyShellState();\n      }\n      if (data.command === \"quick\") {\n        state.shell = \"quick\";\n        state.quickOpen = true;\n        save();\n        applyShellState();\n      }\n    });\n\n    init();\n  </script>\n</body>\n</html>\n";

  if (window.XingJiWidget && window.XingJiWidget.mounted) {
    return;
  }

  let frame = null;

  function setFrameMode(shell, quickOpen) {
    if (!frame) return;

    frame.style.position = "fixed";
    frame.style.border = "0";
    frame.style.background = "transparent";
    frame.style.zIndex = "2147483647";
    frame.style.colorScheme = "normal";

    if (shell === "open") {
      frame.style.inset = "0";
      frame.style.width = "100vw";
      frame.style.height = "100vh";
      frame.style.right = "auto";
      frame.style.bottom = "auto";
      frame.style.borderRadius = "0";
      frame.style.boxShadow = "none";
    } else {
      frame.style.inset = "auto";
      frame.style.right = "0";
      frame.style.bottom = "0";
      frame.style.width = quickOpen ? "min(390px, 100vw)" : "96px";
      frame.style.height = quickOpen ? "min(560px, 100vh)" : "96px";
      frame.style.borderRadius = "0";
      frame.style.boxShadow = "none";
    }
  }

  function mount() {
    if (document.getElementById(WIDGET_ID)) {
      frame = document.getElementById(WIDGET_ID);
      return frame;
    }

    frame = document.createElement("iframe");
    frame.id = WIDGET_ID;
    frame.title = "星寄悬浮球工作台";
    frame.setAttribute("aria-label", "星寄悬浮球工作台");
    frame.setAttribute("allow", "clipboard-read; clipboard-write");
    frame.srcdoc = APP_HTML;
    setFrameMode("open", false);
    document.body.appendChild(frame);
    return frame;
  }

  function send(command) {
    if (!frame || !frame.contentWindow) return;
    frame.contentWindow.postMessage({ type: "xingji-widget-command", command }, "*");
  }

  window.addEventListener("message", (event) => {
    if (!frame || event.source !== frame.contentWindow) return;
    const data = event.data || {};
    if (data.type !== "xingji-widget-shell") return;
    setFrameMode(data.shell, data.quickOpen);
  });

  function ready(fn) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else {
      fn();
    }
  }

  window.XingJiWidget = {
    mounted: true,
    mount,
    open: () => send("open"),
    minimize: () => send("minimize"),
    quick: () => send("quick"),
    remove: () => {
      if (frame) frame.remove();
      frame = null;
      window.XingJiWidget.mounted = false;
    },
    getFrame: () => frame
  };

  ready(mount);
})();
